use clap::Parser;
use reconciler::run_reconciler_loop;
use router::build_router;
use state::AppState;
use tracing::info;

#[derive(Parser, Debug)]
#[command(name = "spaas-control-plane", author, version, about = "SPaaS Control Plane Orchestration Service")]
struct Args {
    #[arg(long, default_value = "0.0.0.0")]
    host: String,

    #[arg(short, long, default_value_t = 8080)]
    port: u16,

    #[arg(long, default_value = "./data/control-plane")]
    data_dir: String,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    spaas_telemetry::init_telemetry("spaas-control-plane");

    let args = Args::parse();
    let addr = format!("{}:{}", args.host, args.port);

    let state = AppState::new(&args.data_dir);

    // Spawn autonomous recovery reconciler loop
    let reconciler_state = state.clone();
    tokio::spawn(async move {
        run_reconciler_loop(reconciler_state).await;
    });

    let app = build_router(state);

    info!("SPaaS Control Plane listening on http://{}", addr);
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

use crate::state::AppState;
use spaas_persistence::WalEvent;
use spaas_protocol::job::{JobLease, JobState};
use spaas_protocol::node::{NodeRecord, NodeState};
use spaas_protocol::rpc::JobDispatchMessage;
use std::sync::atomic::Ordering;
use std::time::Duration;
use tracing::{info, warn};

pub async fn run_reconciler_loop(state: AppState) {
    let mut interval = tokio::time::interval(Duration::from_millis(1500));

    loop {
        interval.tick().await;

        let now = chrono::Utc::now().timestamp_millis();
        let timeout_thresh = now - 20_000; // 20s heartbeat timeout

        // 1. Detect disconnected nodes
        let mut offline_node_ids = Vec::new();
        {
            let mut nodes = state.nodes.write().await;
            for (node_id, node) in nodes.iter_mut() {
                if node.state != NodeState::Offline && node.last_heartbeat_ms < timeout_thresh {
                    node.state = NodeState::Offline;
                    offline_node_ids.push(*node_id);
                    state.metrics.offline_nodes.fetch_add(1, Ordering::Relaxed);
                    state.metrics.active_nodes.fetch_sub(1, Ordering::Relaxed);
                    warn!(node_id = %node_id, "Node missed heartbeats; marked OFFLINE");

                    let updated = node.clone();
                    let _ = state.storage.append_event(WalEvent::UpsertNode { node: updated }).await;
                }
            }
        }

        // 2. Identify jobs with dead nodes, timeouts, or expired leases
        let mut jobs_to_reschedule = Vec::new();
        {
            let mut jobs = state.jobs.write().await;
            for (job_id, job) in jobs.iter_mut() {
                if job.state == JobState::Scheduled || job.state == JobState::Running {
                    let node_died = if let Some(assigned_id) = job.assigned_node_id {
                        offline_node_ids.contains(&assigned_id)
                    } else {
                        false
                    };

                    let is_timed_out = if let Some(started) = job.started_at_ms {
                        now - started > (job.spec.limits.timeout_ms as i64)
                    } else {
                        false
                    };

                    let is_lease_expired = if let Some(ref lease) = job.current_lease {
                        lease.is_expired(now)
                    } else {
                        false
                    };

                    if node_died || is_timed_out || is_lease_expired {
                        let expired_lease = job.current_lease.take();
                        if let Some(l) = expired_lease {
                            let _ = state.storage.append_event(WalEvent::RevokeLease {
                                job_id: *job_id,
                                lease_id: l.lease_id,
                            }).await;
                        }

                        if job.retry_count < job.spec.retry_policy.max_retries {
                            let reason = if is_lease_expired {
                                "Job lease expired without result; recovering and requeuing job"
                            } else if node_died {
                                "Assigned node disconnected; recovering and requeuing job"
                            } else {
                                "Execution timed out; recovering and requeuing job"
                            };

                            warn!(
                                job_id = %job_id,
                                retry = job.retry_count + 1,
                                max = job.spec.retry_policy.max_retries,
                                "{reason}"
                            );

                            let _ = job.transition_to(JobState::Retrying);
                            let _ = job.transition_to(JobState::Queued);
                            state.metrics.retried_jobs.fetch_add(1, Ordering::Relaxed);
                            jobs_to_reschedule.push(*job_id);

                            let updated_job = job.clone();
                            let _ = state.storage.append_event(WalEvent::UpsertJob { job: updated_job }).await;
                        } else {
                            warn!(
                                job_id = %job_id,
                                "Job exceeded max retries; marking FAILED"
                            );
                            let _ = job.transition_to(JobState::Failed);
                            job.error_message = Some("Node disappeared or lease expired with retries exhausted".into());
                            state.metrics.failed_jobs.fetch_add(1, Ordering::Relaxed);

                            let updated_job = job.clone();
                            let _ = state.storage.append_event(WalEvent::UpsertJob { job: updated_job }).await;
                        }
                    }
                }
            }
        }

        // 3. Attempt to schedule pending queued jobs
        let eligible_nodes: Vec<NodeRecord> = {
            let nodes = state.nodes.read().await;
            nodes.values().cloned().collect()
        };

        let queued_job_ids: Vec<uuid::Uuid> = {
            let jobs = state.jobs.read().await;
            jobs.iter()
                .filter(|(_, j)| j.state == JobState::Queued)
                .map(|(id, _)| *id)
                .collect()
        };

        for q_id in queued_job_ids {
            let mut jobs = state.jobs.write().await;
            if let Some(job) = jobs.get_mut(&q_id) {
                if let Ok(selected) = state.scheduler.schedule_workload(&job.spec, &eligible_nodes) {
                    if !selected.is_empty() {
                        let primary = selected[0];
                        let lease = JobLease::new(q_id, primary, 30_000);

                        job.assigned_node_id = Some(primary);
                        job.current_lease = Some(lease.clone());
                        let _ = job.transition_to(JobState::Scheduled);

                        let artifacts = state.wasm_artifacts.read().await;
                        let wasm_bytes = artifacts.get(&job.spec.artifact_sha256).cloned();

                        let dispatch = JobDispatchMessage {
                            job_id: q_id,
                            lease_id: lease.lease_id,
                            lease_expires_at_ms: lease.expires_at_ms,
                            spec: job.spec.clone(),
                            wasm_bytes,
                            dispatched_at_ms: now,
                        };

                        let mut dispatches = state.dispatches.write().await;
                        dispatches.insert(primary, dispatch);

                        let updated_job = job.clone();
                        let _ = state.storage.append_event(WalEvent::GrantLease { lease }).await;
                        let _ = state.storage.append_event(WalEvent::UpsertJob { job: updated_job }).await;

                        info!(job_id = %q_id, node_id = %primary, "Queued job scheduled by reconciler with renewable lease");
                    }
                }
            }
        }
    }
}

use crate::handlers::*;
use crate::state::AppState;
use axum::{
    routing::{get, post},
    Router,
};
use tower_http::cors::{Any, CorsLayer};

pub fn build_router(state: AppState) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    Router::new()
        // Node Management & Qualification
        .route("/api/v1/nodes/register", post(register_node))
        .route("/api/v1/nodes/heartbeat", post(heartbeat))
        .route("/api/v1/nodes/:node_id/poll", get(poll_job))
        .route("/api/v1/nodes/:node_id/qualification", post(qualify_node).get(get_node_qualification))
        .route("/api/v1/nodes/results", post(submit_result))
        .route("/api/v1/nodes", get(list_nodes))
        // Job Management & Leases
        .route("/api/v1/jobs", post(submit_job).get(list_jobs))
        .route("/api/v1/jobs/:job_id", get(get_job))
        .route("/api/v1/jobs/:job_id/lease/renew", post(renew_job_lease))
        .route("/api/v1/jobs/:job_id/cancel", post(cancel_job))
        // System Observability & Ledger
        .route("/api/v1/system/health", get(get_health))
        .route("/api/v1/metering", get(get_metering))
        .route("/api/v1/audit", get(get_audit_log))
        .route("/metrics", get(get_metrics))
        .layer(cors)
        .with_state(state)
}

use spaas_metering::MeteringLedger;
use spaas_persistence::{AuditRecord, DurableStorage, WalEvent};
use spaas_protocol::job::{JobLease, JobRecord};
use spaas_protocol::node::NodeRecord;
use spaas_protocol::rpc::JobDispatchMessage;
use spaas_scheduler_core::EdgeScheduler;
use spaas_security::keys::KeyPair;
use spaas_telemetry::MetricsRegistry;
use spaas_verification::VerificationEngine;
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use tokio::sync::RwLock;
use tracing::info;
use uuid::Uuid;

#[derive(Clone)]
pub struct AppState {
    pub storage: Arc<DurableStorage>,
    pub nodes: Arc<RwLock<HashMap<Uuid, NodeRecord>>>,
    pub jobs: Arc<RwLock<HashMap<Uuid, JobRecord>>>,
    pub dispatches: Arc<RwLock<HashMap<Uuid, JobDispatchMessage>>>,
    pub wasm_artifacts: Arc<RwLock<HashMap<String, Vec<u8>>>>,
    pub scheduler: Arc<EdgeScheduler>,
    pub verification: Arc<VerificationEngine>,
    pub ledger: Arc<RwLock<MeteringLedger>>,
    pub metrics: Arc<MetricsRegistry>,
    pub server_keypair: Arc<KeyPair>,
    pub audit_log: Arc<RwLock<Vec<AuditRecord>>>,
    pub started_at_ms: i64,
}

impl AppState {
    pub fn new(data_dir: impl AsRef<Path>) -> Self {
        let storage = Arc::new(
            DurableStorage::open(data_dir.as_ref())
                .unwrap_or_else(|e| panic!("Failed to open durable storage at {:?}: {e}", data_dir.as_ref())),
        );

        let recovered = storage.initial_state.clone();

        info!(
            recovered_nodes = recovered.nodes.len(),
            recovered_jobs = recovered.jobs.len(),
            recovered_metering = recovered.metering_records.len(),
            "Durable state loaded into Control Plane memory"
        );

        let mut ledger = MeteringLedger::new();
        // Restore accounts and records into ledger
        for record in &recovered.metering_records {
            let _ = ledger.record_job_execution(
                record.job_id,
                record.node_id,
                &record.idempotency_key,
                &record.provider_public_key,
                &record.submitter_public_key,
                record.usage.clone(),
                record.is_verified,
            );
        }

        Self {
            storage,
            nodes: Arc::new(RwLock::new(recovered.nodes)),
            jobs: Arc::new(RwLock::new(recovered.jobs)),
            dispatches: Arc::new(RwLock::new(HashMap::new())),
            wasm_artifacts: Arc::new(RwLock::new(recovered.wasm_artifacts)),
            scheduler: Arc::new(EdgeScheduler::new(Default::default())),
            verification: Arc::new(VerificationEngine::new()),
            ledger: Arc::new(RwLock::new(ledger)),
            metrics: Arc::new(MetricsRegistry::new()),
            server_keypair: Arc::new(KeyPair::generate()),
            audit_log: Arc::new(RwLock::new(recovered.audit_log)),
            started_at_ms: chrono::Utc::now().timestamp_millis(),
        }
    }

    pub async fn log_audit(&self, event_type: &str, entity_id: &str, details: &str) {
        let record = AuditRecord {
            timestamp_ms: chrono::Utc::now().timestamp_millis(),
            event_type: event_type.to_string(),
            entity_id: entity_id.to_string(),
            details: details.to_string(),
        };
        {
            let mut log = self.audit_log.write().await;
            log.push(record.clone());
        }
        let _ = self.storage.append_event(WalEvent::AppendAudit { record }).await;
    }

    pub async fn upsert_node(&self, node: NodeRecord) {
        {
            let mut nodes = self.nodes.write().await;
            nodes.insert(node.node_id, node.clone());
        }
        let _ = self.storage.append_event(WalEvent::UpsertNode { node }).await;
    }

    pub async fn upsert_job(&self, job: JobRecord) {
        {
            let mut jobs = self.jobs.write().await;
            jobs.insert(job.job_id, job.clone());
        }
        let _ = self.storage.append_event(WalEvent::UpsertJob { job }).await;
    }

    pub async fn grant_lease(&self, lease: JobLease) {
        {
            let mut jobs = self.jobs.write().await;
            if let Some(job) = jobs.get_mut(&lease.job_id) {
                job.current_lease = Some(lease.clone());
            }
        }
        let _ = self.storage.append_event(WalEvent::GrantLease { lease }).await;
    }

    #[allow(dead_code)]
    pub async fn renew_lease(&self, lease: JobLease) {
        {
            let mut jobs = self.jobs.write().await;
            if let Some(job) = jobs.get_mut(&lease.job_id) {
                job.current_lease = Some(lease.clone());
            }
        }
        let _ = self.storage.append_event(WalEvent::RenewLease { lease }).await;
    }

    #[allow(dead_code)]
    pub async fn revoke_lease(&self, job_id: Uuid, lease_id: Uuid) {
        {
            let mut jobs = self.jobs.write().await;
            if let Some(job) = jobs.get_mut(&job_id) {
                job.current_lease = None;
            }
        }
        let _ = self.storage.append_event(WalEvent::RevokeLease { job_id, lease_id }).await;
    }

    pub async fn store_wasm_artifact(&self, sha256: String, bytes: Vec<u8>) {
        {
            let mut artifacts = self.wasm_artifacts.write().await;
            artifacts.insert(sha256.clone(), bytes.clone());
        }
        let _ = self.storage.append_event(WalEvent::StoreArtifact { sha256, bytes }).await;
    }
}

impl Default for AppState {
    fn default() -> Self {
        Self::new("./data/control-plane")
    }
}

