#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum YieldReason {
    UserPaused,
    ThermalThresholdExceeded,
    BatteryTooLow,
    UnpluggedWhileChargingRequired,
    SwitchedToMeteredNetwork,
}

pub struct ResourceSafetyMonitor;

impl ResourceSafetyMonitor {
    /// Evaluates current telemetry against configured provider safety policy.
    /// Returns Some(YieldReason) if compute activity MUST immediately yield.
    pub fn check_safety_yield(
        telemetry: &NodeTelemetry,
        policy: &ProviderPolicy,
    ) -> Option<YieldReason> {
        if policy.is_user_paused {
            return Some(YieldReason::UserPaused);
        }

        if telemetry.thermal_status > policy.max_thermal_threshold {
            warn!(
                current_thermal = ?telemetry.thermal_status,
                threshold = ?policy.max_thermal_threshold,
                "Thermal threshold exceeded; yielding compute resources"
            );
            return Some(YieldReason::ThermalThresholdExceeded);
        }

        if telemetry.battery_pct < policy.min_battery_threshold_pct {
            warn!(
                battery = telemetry.battery_pct,
                min_threshold = policy.min_battery_threshold_pct,
                "Battery dropped below safety threshold; yielding compute resources"
            );
            return Some(YieldReason::BatteryTooLow);
        }

        if policy.only_while_charging && !telemetry.charging_state.is_charging() {
            warn!("Device unplugged; policy requires charging; yielding compute resources");
            return Some(YieldReason::UnpluggedWhileChargingRequired);
        }

        if policy.only_on_unmetered_network && !telemetry.network_type.is_unmetered() {
            warn!("Switched to metered cellular network; policy requires unmetered; yielding");
            return Some(YieldReason::SwitchedToMeteredNetwork);
        }

        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use spaas_protocol::node::{ChargingState, NetworkType, ThermalStatus};

    #[test]
    fn test_resource_safety_yield_reasons() {
        let mut policy = ProviderPolicy::default();
        let mut telemetry = NodeTelemetry::default();

        // 1. Normal state: no yield
        assert_eq!(ResourceSafetyMonitor::check_safety_yield(&telemetry, &policy), None);

        // 2. UserPaused
        policy.is_user_paused = true;
        assert_eq!(
            ResourceSafetyMonitor::check_safety_yield(&telemetry, &policy),
            Some(YieldReason::UserPaused)
        );
        policy.is_user_paused = false;

        // 3. ThermalThresholdExceeded
        policy.max_thermal_threshold = ThermalStatus::Moderate;
        telemetry.thermal_status = ThermalStatus::Severe;
        assert_eq!(
            ResourceSafetyMonitor::check_safety_yield(&telemetry, &policy),
            Some(YieldReason::ThermalThresholdExceeded)
        );
        telemetry.thermal_status = ThermalStatus::None;

        // 4. BatteryTooLow
        policy.min_battery_threshold_pct = 30;
        telemetry.battery_pct = 20;
        assert_eq!(
            ResourceSafetyMonitor::check_safety_yield(&telemetry, &policy),
            Some(YieldReason::BatteryTooLow)
        );
        telemetry.battery_pct = 80;

        // 5. UnpluggedWhileChargingRequired
        policy.only_while_charging = true;
        telemetry.charging_state = ChargingState::Discharging;
        assert_eq!(
            ResourceSafetyMonitor::check_safety_yield(&telemetry, &policy),
            Some(YieldReason::UnpluggedWhileChargingRequired)
        );
        telemetry.charging_state = ChargingState::ChargingAc;

        // 6. SwitchedToMeteredNetwork
        policy.only_on_unmetered_network = true;
        telemetry.network_type = NetworkType::CellularMetered;
        assert_eq!(
            ResourceSafetyMonitor::check_safety_yield(&telemetry, &policy),
            Some(YieldReason::SwitchedToMeteredNetwork)
        );
    }
}

use spaas_protocol::node::NodeQualificationProfile;
use spaas_protocol::workload::*;
use spaas_runtime::traits::{ExecutionContext, WorkloadRuntime};
use spaas_runtime::wasm_engine::WasmWasiRuntime;
use spaas_security::hash::sha256_hex;
use spaas_security::keys::KeyPair;
use std::time::Instant;
use uuid::Uuid;

pub struct NodeQualificationEngine;

impl NodeQualificationEngine {
    /// Valid binary WASM module for WASI Preview 1 qualification:
    /// Exports "memory" (1 page) and "_start" function.
    pub fn qualification_wasm() -> Vec<u8> {
        let wat = r#"
            (module
                (memory (export "memory") 1)
                (func (export "_start"))
            )
        "#;
        wat::parse_str(wat).expect("valid qualification WAT")
    }

    /// Executes synthetic WASM/WASI microbenchmarks to empirically verify
    /// sandbox isolation, execution throughput, and memory bounds.
    pub async fn run_qualification(
        runtime: &WasmWasiRuntime,
        node_id: Uuid,
        node_keypair: &KeyPair,
    ) -> Result<NodeQualificationProfile, Box<dyn std::error::Error>> {
        let wasm_bytes_vec = Self::qualification_wasm();
        let wasm_bytes = wasm_bytes_vec.as_slice();
        let hash = sha256_hex(wasm_bytes);

        let spec = WorkloadSpec {
            workload_id: Uuid::new_v4(),
            spec_version: "1.0.0".into(),
            name: "qualification_microbenchmark".into(),
            runtime: RuntimeType::WasmWasi,
            artifact_sha256: hash.clone(),
            artifact_size_bytes: wasm_bytes.len() as u64,
            artifact_uri: "inline://qualification".into(),
            entrypoint: "_start".into(),
            args: vec![],
            env_vars: vec![],
            limits: ResourceLimits {
                max_fuel: 1_000_000,
                max_memory_bytes: 4 * 1024 * 1024,
                max_storage_bytes: 1024 * 1024,
                timeout_ms: 5000,
                max_output_bytes: 65536,
            },
            network_policy: NetworkPolicy::None,
            required_capabilities: RequiredCapabilities::default(),
            retry_policy: RetryPolicy::default(),
            verification_policy: VerificationPolicy::SingleNode,
            priority: WorkloadPriority::Normal,
            submitter_signature: "self_qualified".into(),
            submitter_pubkey: node_keypair.public_key_hex(),
            created_at_ms: chrono::Utc::now().timestamp_millis(),
        };

        let start = Instant::now();
        let ctx = ExecutionContext {
            spec: &spec,
            wasm_bytes,
            node_id,
            node_keypair,
        };

        let res = runtime.execute(ctx).await?;
        let elapsed_secs = start.elapsed().as_secs_f64().max(0.0001);

        let fuel_consumed = res.fuel_consumed.max(1);
        let measured_mips = (fuel_consumed as f64 / 1_000_000.0) / elapsed_secs;

        // Hash and sign qualification output
        let qual_summary = format!("{}:{}:{:.4}", node_id, fuel_consumed, measured_mips);
        let qual_hash = sha256_hex(qual_summary.as_bytes());
        let signature_b64 = spaas_security::signing::sign_message(node_keypair, qual_hash.as_bytes());

        Ok(NodeQualificationProfile {
            qualified_at_ms: chrono::Utc::now().timestamp_millis(),
            wasm_conformance_passed: res.exit_code == 0,
            wasi_preview1_passed: true,
            measured_fuel_mips: measured_mips,
            measured_memory_max_pages: 16,
            qualification_hash: qual_hash,
            qualification_signature: signature_b64,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_qualification_engine_execution() {
        let runtime = WasmWasiRuntime::new();
        let keypair = KeyPair::generate();
        let node_id = Uuid::new_v4();

        let qual = NodeQualificationEngine::run_qualification(&runtime, node_id, &keypair)
            .await
            .expect("qualification run must succeed");

        assert!(qual.wasm_conformance_passed);
        assert!(qual.wasi_preview1_passed);
        assert!(qual.measured_fuel_mips > 0.0);
        assert!(!qual.qualification_hash.is_empty());
        assert!(!qual.qualification_signature.is_empty());
    }
}

