#[derive(Error, Debug)]
pub enum PersistenceError {
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("Serialization error: {0}")]
    Serialization(#[from] serde_json::Error),
    #[error("Corrupt WAL entry at sequence {0}: {1}")]
    CorruptWal(u64, String),
    #[error("Lock acquisition failed: {0}")]
    LockError(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuditRecord {
    pub timestamp_ms: i64,
    pub event_type: String,
    pub entity_id: String,
    pub details: String,
}

/// Durable events recorded sequentially to Write-Ahead Log (WAL)
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum WalEvent {
    UpsertNode { node: NodeRecord },
    RemoveNode { node_id: Uuid },
    UpsertJob { job: JobRecord },
    GrantLease { lease: JobLease },
    RenewLease { lease: JobLease },
    RevokeLease { job_id: Uuid, lease_id: Uuid },
    AppendMetering { record: MeteringRecord },
    AppendAudit { record: AuditRecord },
    StoreArtifact { sha256: String, bytes: Vec<u8> },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WalEntry {
    pub seq: u64,
    pub timestamp_ms: i64,
    pub event: WalEvent,
    pub checksum: u32,
}

impl WalEntry {
    pub fn compute_checksum(seq: u64, timestamp_ms: i64, event_json: &str) -> u32 {
        let mut crc = 0xFFFFFFFFu32;
        for b in seq.to_le_bytes().iter().chain(timestamp_ms.to_le_bytes().iter()).chain(event_json.as_bytes().iter()) {
            crc ^= *b as u32;
            for _ in 0..8 {
                if (crc & 1) != 0 {
                    crc = (crc >> 1) ^ 0xEDB88320;
                } else {
                    crc >>= 1;
                }
            }
        }
        !crc
    }
}

/// State recovered after replaying snapshots and WAL records
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct RecoveredState {
    pub nodes: HashMap<Uuid, NodeRecord>,
    pub jobs: HashMap<Uuid, JobRecord>,
    pub metering_records: Vec<MeteringRecord>,
    pub audit_log: Vec<AuditRecord>,
    pub wasm_artifacts: HashMap<String, Vec<u8>>,
    pub last_seq: u64,
}

pub struct DurableStorage {
    data_dir: PathBuf,
    snapshot_path: PathBuf,
    next_seq: AtomicU64,
    writer_lock: tokio::sync::Mutex<BufWriter<File>>,
    state: Arc<RwLock<RecoveredState>>,
    pub initial_state: RecoveredState,
}

impl DurableStorage {
    /// Opens or initializes a durable storage instance at `data_dir`
    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, PersistenceError> {
        let data_dir = data_dir.as_ref().to_path_buf();
        fs::create_dir_all(&data_dir)?;

        let wal_path = data_dir.join("spaas.wal");
        let snapshot_path = data_dir.join("spaas.snapshot.json");

        // 1. Recover state from snapshot if present
        let mut state = if snapshot_path.exists() {
            let snap_file = File::open(&snapshot_path)?;
            let reader = BufReader::new(snap_file);
            match serde_json::from_reader::<_, RecoveredState>(reader) {
                Ok(snap) => {
                    info!("Loaded durable snapshot with sequence up to {}", snap.last_seq);
                    snap
                }
                Err(e) => {
                    warn!("Corrupted snapshot detected (will reconstruct from WAL): {e}");
                    RecoveredState::default()
                }
            }
        } else {
            RecoveredState::default()
        };

        // 2. Replay WAL entries succeeding snapshot sequence
        let mut last_seq = state.last_seq;
        if wal_path.exists() {
            let wal_file = File::open(&wal_path)?;
            let reader = BufReader::new(wal_file);

            for (idx, line_res) in reader.lines().enumerate() {
                let line = line_res?;
                if line.trim().is_empty() {
                    continue;
                }
                let entry: WalEntry = serde_json::from_str(&line).map_err(|e| {
                    PersistenceError::CorruptWal(idx as u64, format!("JSON decode failed: {e}"))
                })?;

                // Validate checksum
                let event_json = serde_json::to_string(&entry.event)?;
                let expected = WalEntry::compute_checksum(entry.seq, entry.timestamp_ms, &event_json);
                if entry.checksum != expected {
                    return Err(PersistenceError::CorruptWal(
                        entry.seq,
                        format!("Checksum mismatch: expected {expected}, got {}", entry.checksum),
                    ));
                }

                if entry.seq > state.last_seq {
                    Self::apply_event_to_state(&mut state, entry.event);
                    last_seq = entry.seq;
                }
            }
            info!("WAL replay completed successfully up to sequence {}", last_seq);
        }

        state.last_seq = last_seq;

        // Open WAL file for appending
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&wal_path)?;
        let writer = BufWriter::new(file);

        Ok(Self {
            data_dir,
            snapshot_path,
            next_seq: AtomicU64::new(last_seq + 1),
            writer_lock: tokio::sync::Mutex::new(writer),
            initial_state: state.clone(),
            state: Arc::new(RwLock::new(state)),
        })
    }

    fn apply_event_to_state(state: &mut RecoveredState, event: WalEvent) {
        match event {
            WalEvent::UpsertNode { node } => {
                state.nodes.insert(node.node_id, node);
            }
            WalEvent::RemoveNode { node_id } => {
                state.nodes.remove(&node_id);
            }
            WalEvent::UpsertJob { job } => {
                state.jobs.insert(job.job_id, job);
            }
            WalEvent::GrantLease { lease } => {
                if let Some(job) = state.jobs.get_mut(&lease.job_id) {
                    job.current_lease = Some(lease);
                }
            }
            WalEvent::RenewLease { lease } => {
                if let Some(job) = state.jobs.get_mut(&lease.job_id) {
                    job.current_lease = Some(lease);
                }
            }
            WalEvent::RevokeLease { job_id, .. } => {
                if let Some(job) = state.jobs.get_mut(&job_id) {
                    job.current_lease = None;
                }
            }
            WalEvent::AppendMetering { record } => {
                state.metering_records.push(record);
            }
            WalEvent::AppendAudit { record } => {
                state.audit_log.push(record);
            }
            WalEvent::StoreArtifact { sha256, bytes } => {
                state.wasm_artifacts.insert(sha256, bytes);
            }
        }
    }

    /// Appends an event to the WAL and applies it to in-memory state
    pub async fn append_event(&self, event: WalEvent) -> Result<u64, PersistenceError> {
        let seq = self.next_seq.fetch_add(1, Ordering::SeqCst);
        let timestamp_ms = Utc::now().timestamp_millis();
        let event_json = serde_json::to_string(&event)?;
        let checksum = WalEntry::compute_checksum(seq, timestamp_ms, &event_json);

        let entry = WalEntry {
            seq,
            timestamp_ms,
            event: event.clone(),
            checksum,
        };

        let entry_line = serde_json::to_string(&entry)? + "\n";

        // 1. Write to WAL with lock
        {
            let mut writer = self.writer_lock.lock().await;
            writer.write_all(entry_line.as_bytes())?;
            writer.flush()?;
        }

        // 2. Mutate in-memory state
        {
            let mut state = self.state.write().await;
            Self::apply_event_to_state(&mut state, event);
            state.last_seq = seq;
        }

        Ok(seq)
    }

    /// Creates an atomic snapshot of current state and compacts WAL
    pub async fn checkpoint_snapshot(&self) -> Result<(), PersistenceError> {
        let snap_tmp = self.data_dir.join("spaas.snapshot.json.tmp");
        let state_clone = {
            let state = self.state.read().await;
            state.clone()
        };

        // Write snapshot to temporary file
        let file = File::create(&snap_tmp)?;
        serde_json::to_writer_pretty(file, &state_clone)?;

        // Atomic file rename
        fs::rename(&snap_tmp, &self.snapshot_path)?;
        info!("Atomic checkpoint snapshot created at seq {}", state_clone.last_seq);

        Ok(())
    }

    /// Returns a reference to the read/write recovered state
    pub fn state(&self) -> Arc<RwLock<RecoveredState>> {
        self.state.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use spaas_protocol::workload::WorkloadSpec;
    use tempfile::tempdir;

    #[tokio::test]
    async fn test_durable_storage_recovery() {
        let dir = tempdir().unwrap();
        let storage = DurableStorage::open(dir.path()).unwrap();

        // 1. Append a node and a job
        let node = NodeRecord {
            node_id: Uuid::new_v4(),
            public_key: "pubkey123".into(),
            device_type: spaas_protocol::node::NodeDeviceType::LinuxDesktop,
            enrollment: spaas_protocol::node::EnrollmentStatus::Enrolled,
            state: spaas_protocol::node::NodeState::Idle,
            capabilities: Default::default(),
            telemetry: Default::default(),
            policy: Default::default(),
            qualification: None,
            enrolled_at_ms: 1000,
            last_heartbeat_ms: 1000,
            region: "local".into(),
            is_simulated: false,
        };

        storage.append_event(WalEvent::UpsertNode { node: node.clone() }).await.unwrap();

        let job_id = Uuid::new_v4();
        let job = JobRecord::new(WorkloadSpec {
            workload_id: job_id,
            spec_version: "1.0.0".into(),
            name: "test_job".into(),
            runtime: Default::default(),
            artifact_sha256: "hash123".into(),
            artifact_size_bytes: 512,
            artifact_uri: "inline://hash123".into(),
            entrypoint: "_start".into(),
            args: vec![],
            env_vars: vec![],
            limits: Default::default(),
            network_policy: Default::default(),
            required_capabilities: Default::default(),
            retry_policy: Default::default(),
            verification_policy: Default::default(),
            priority: Default::default(),
            submitter_signature: "".into(),
            submitter_pubkey: "".into(),
            created_at_ms: 1000,
        });

        storage.append_event(WalEvent::UpsertJob { job: job.clone() }).await.unwrap();

        // 2. Grant lease
        let lease = JobLease::new(job_id, node.node_id, 30_000);
        storage.append_event(WalEvent::GrantLease { lease: lease.clone() }).await.unwrap();

        // Drop current storage handle to simulate sudden restart/process exit
        drop(storage);

        // 3. Reopen storage from the same directory
        let restored = DurableStorage::open(dir.path()).unwrap();
        let state_arc = restored.state();
        let state = state_arc.read().await;

        assert_eq!(state.nodes.len(), 1);
        assert_eq!(state.jobs.len(), 1);
        let recovered_job = state.jobs.get(&job_id).unwrap();
        assert!(recovered_job.current_lease.is_some());
        assert_eq!(recovered_job.current_lease.as_ref().unwrap().lease_id, lease.lease_id);
    }

    #[tokio::test]
    async fn test_corrupted_crc_wal_rejected() {
        let dir = tempdir().unwrap();
        let wal_path = dir.path().join("spaas.wal");

        // Write an entry with forged/corrupted checksum
        let event = WalEvent::UpsertJob { job: JobRecord::new(WorkloadSpec::default()) };
        let entry = WalEntry {
            seq: 1,
            timestamp_ms: 1000,
            event,
            checksum: 999999, // Corrupted CRC
        };
        let line = serde_json::to_string(&entry).unwrap() + "\n";
        fs::write(&wal_path, line).unwrap();

        let res = DurableStorage::open(dir.path());
        match res {
            Err(PersistenceError::CorruptWal(1, _)) => {}
            _ => panic!("Expected CorruptWal(1, _) error"),
        }
    }

    #[tokio::test]
    async fn test_malformed_json_wal_rejected() {
        let dir = tempdir().unwrap();
        let wal_path = dir.path().join("spaas.wal");
        fs::write(&wal_path, "{broken_json\n").unwrap();

        let res = DurableStorage::open(dir.path());
        match res {
            Err(PersistenceError::CorruptWal(0, _)) => {}
            _ => panic!("Expected CorruptWal(0, _) error"),
        }
    }

    #[tokio::test]
    async fn test_snapshot_checkpoint_and_recovery() {
        let dir = tempdir().unwrap();
        let storage = DurableStorage::open(dir.path()).unwrap();

        let _job_id = Uuid::new_v4();
        let job = JobRecord::new(WorkloadSpec::default());
        storage.append_event(WalEvent::UpsertJob { job: job.clone() }).await.unwrap();

        // Checkpoint snapshot
        storage.checkpoint_snapshot().await.unwrap();
        assert!(dir.path().join("spaas.snapshot.json").exists());

        // Append more events after snapshot
        let artifact_hash = "sha256_wasm_art".to_string();
        storage.append_event(WalEvent::StoreArtifact {
            sha256: artifact_hash.clone(),
            bytes: vec![1, 2, 3, 4],
        }).await.unwrap();

        drop(storage);

        // Reopen storage: should load snapshot and replay subsequent artifact event
        let restored = DurableStorage::open(dir.path()).unwrap();
        let state = restored.state().read().await.clone();
        assert_eq!(state.jobs.len(), 1);
        assert!(state.wasm_artifacts.contains_key(&artifact_hash));

        // Test RemoveNode, RenewLease, and RevokeLease
        let node_id = Uuid::new_v4();
        let dummy_node = NodeRecord {
            node_id,
            public_key: "pk".into(),
            device_type: spaas_protocol::node::NodeDeviceType::SimulatedNode,
            enrollment: spaas_protocol::node::EnrollmentStatus::Enrolled,
            state: spaas_protocol::node::NodeState::Idle,
            capabilities: Default::default(),
            telemetry: Default::default(),
            policy: Default::default(),
            qualification: None,
            enrolled_at_ms: 0,
            last_heartbeat_ms: 0,
            region: "us".into(),
            is_simulated: true,
        };
        restored.append_event(WalEvent::UpsertNode { node: dummy_node }).await.unwrap();
        assert_eq!(restored.state().read().await.nodes.len(), 1);

        restored.append_event(WalEvent::RemoveNode { node_id }).await.unwrap();
        assert_eq!(restored.state().read().await.nodes.len(), 0);

        let mut lease = JobLease::new(job.job_id, node_id, 1000);
        restored.append_event(WalEvent::GrantLease { lease: lease.clone() }).await.unwrap();
        lease.renew(2000);
        restored.append_event(WalEvent::RenewLease { lease: lease.clone() }).await.unwrap();
        assert_eq!(restored.state().read().await.jobs.get(&job.job_id).unwrap().current_lease.as_ref().unwrap().term, 2);

        restored.append_event(WalEvent::RevokeLease { job_id: job.job_id, lease_id: lease.lease_id }).await.unwrap();
        assert!(restored.state().read().await.jobs.get(&job.job_id).unwrap().current_lease.is_none());
    }

    #[tokio::test]
    async fn test_corrupted_snapshot_recovers_gracefully() {
        let dir = tempdir().unwrap();
        // Write invalid JSON snapshot
        std::fs::write(dir.path().join("spaas.snapshot.json"), b"invalid json content").unwrap();

        // Storage open should succeed and fall back to default state
        let storage = DurableStorage::open(dir.path()).unwrap();
        assert_eq!(storage.state().read().await.nodes.len(), 0);
    }

    #[test]
    fn test_persistence_error_display() {
        let errs = vec![
            PersistenceError::Io(std::io::Error::new(std::io::ErrorKind::NotFound, "file not found")),
            PersistenceError::CorruptWal(42, "checksum error".into()),
            PersistenceError::Serialization(serde_json::from_str::<String>("bad_json").unwrap_err()),
            PersistenceError::LockError("lock poisoned".into()),
        ];
        for err in errs {
            assert!(!format!("{}", err).is_empty());
        }
    }
}

use serde::{Deserialize, Serialize};
use std::fmt;

/// Verification Evidence Classification per SPaaS Specification (Section 11)
/// Never promote IMPLEMENTED_UNPROVEN, HARDWARE_REQUIRED, or UNSUPPORTED to production-proven.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum VerificationEvidenceClass {
    /// Fully verified on real production target hardware with passing tests
    Proven,
    /// Verified on an official platform emulator (e.g. Android Emulator via AVD)
    EmulatorProven,
    /// Verified inside the distributed system simulation lab (Podman/synthetic nodes)
    SimulationProven,
    /// Fully coded and structurally integrated, but lacking hardware runtime execution
    ImplementedUnproven,
    /// Requires specific physical hardware (e.g., Qualcomm NPU, AVF pKVM, Secure Element)
    HardwareRequired,
    /// Explicitly unsupported on the specified architecture or platform
    Unsupported,
}

impl VerificationEvidenceClass {
    /// Returns true if this evidence class permits production certification
    pub fn is_production_certified(&self) -> bool {
        matches!(self, Self::Proven)
    }

    /// Returns true if verified via simulated or emulated environments
    pub fn is_test_verified(&self) -> bool {
        matches!(self, Self::Proven | Self::EmulatorProven | Self::SimulationProven)
    }

    /// Returns a human-readable display label
    pub fn label(&self) -> &'static str {
        match self {
            Self::Proven => "PROVEN",
            Self::EmulatorProven => "EMULATOR-PROVEN",
            Self::SimulationProven => "SIMULATION-PROVEN",
            Self::ImplementedUnproven => "IMPLEMENTED-UNPROVEN",
            Self::HardwareRequired => "HARDWARE-REQUIRED",
            Self::Unsupported => "UNSUPPORTED",
        }
    }
}

impl fmt::Display for VerificationEvidenceClass {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.label())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_evidence_classification_promotion_rules() {
        assert!(VerificationEvidenceClass::Proven.is_production_certified());
        assert!(!VerificationEvidenceClass::EmulatorProven.is_production_certified());
        assert!(!VerificationEvidenceClass::SimulationProven.is_production_certified());
        assert!(!VerificationEvidenceClass::ImplementedUnproven.is_production_certified());
        assert!(!VerificationEvidenceClass::HardwareRequired.is_production_certified());
        assert!(!VerificationEvidenceClass::Unsupported.is_production_certified());

        assert!(VerificationEvidenceClass::SimulationProven.is_test_verified());
        assert!(VerificationEvidenceClass::EmulatorProven.is_test_verified());
        assert!(!VerificationEvidenceClass::ImplementedUnproven.is_test_verified());
        assert!(!VerificationEvidenceClass::HardwareRequired.is_test_verified());
        assert!(!VerificationEvidenceClass::Unsupported.is_test_verified());

        // Labels and Display
        assert_eq!(format!("{}", VerificationEvidenceClass::Proven), "PROVEN");
        assert_eq!(format!("{}", VerificationEvidenceClass::EmulatorProven), "EMULATOR-PROVEN");
        assert_eq!(format!("{}", VerificationEvidenceClass::SimulationProven), "SIMULATION-PROVEN");
        assert_eq!(format!("{}", VerificationEvidenceClass::ImplementedUnproven), "IMPLEMENTED-UNPROVEN");
        assert_eq!(format!("{}", VerificationEvidenceClass::HardwareRequired), "HARDWARE-REQUIRED");
        assert_eq!(format!("{}", VerificationEvidenceClass::Unsupported), "UNSUPPORTED");
    }

    #[test]
    fn test_serialization() {
        let json = serde_json::to_string(&VerificationEvidenceClass::SimulationProven).unwrap();
        assert_eq!(json, "\"SIMULATION_PROVEN\"");
        let deserialized: VerificationEvidenceClass = serde_json::from_str(&json).unwrap();
        assert_eq!(deserialized, VerificationEvidenceClass::SimulationProven);
    }
}

use crate::error::ProtocolError;
use crate::workload::WorkloadSpec;
use serde::{Deserialize, Serialize};
use std::fmt;
use uuid::Uuid;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum JobState {
    /// Workload submitted, waiting in scheduling priority queue
    Queued,
    /// Dispatched and bound to an eligible node
    Scheduled,
    /// Node reported execution in progress inside WASM sandbox
    Running,
    /// Node returned output, currently undergoing cryptographic or consensus verification
    Verifying,
    /// Result verified, accepted, and metered (Terminal state)
    Completed,
    /// Node dropped or errored; job queued for retry on a different node
    Retrying,
    /// Execution deadline exceeded (Terminal or Retrying)
    TimedOut,
    /// Unrecoverable failure or max retries exceeded (Terminal state)
    Failed,
    /// Cancelled explicitly by submitter or operator (Terminal state)
    Cancelled,
}

impl JobState {
    pub fn is_terminal(&self) -> bool {
        matches!(self, Self::Completed | Self::Failed | Self::Cancelled)
    }

    /// Validates if transition from `self` to `next` is mathematically and protocol legal
    pub fn can_transition_to(&self, next: JobState) -> bool {
        if *self == next {
            // Idempotent self-transitions allowed
            return true;
        }
        if self.is_terminal() {
            // Terminal states cannot transition to anything else
            return false;
        }

        match (self, next) {
            (JobState::Queued, JobState::Scheduled) => true,
            (JobState::Queued, JobState::Cancelled) => true,

            (JobState::Scheduled, JobState::Running) => true,
            (JobState::Scheduled, JobState::Retrying) => true,
            (JobState::Scheduled, JobState::TimedOut) => true,
            (JobState::Scheduled, JobState::Failed) => true,
            (JobState::Scheduled, JobState::Cancelled) => true,

            (JobState::Running, JobState::Verifying) => true,
            (JobState::Running, JobState::Retrying) => true,
            (JobState::Running, JobState::TimedOut) => true,
            (JobState::Running, JobState::Failed) => true,
            (JobState::Running, JobState::Cancelled) => true,

            (JobState::Verifying, JobState::Completed) => true,
            (JobState::Verifying, JobState::Retrying) => true,
            (JobState::Verifying, JobState::Failed) => true,
            (JobState::Verifying, JobState::Cancelled) => true,

            (JobState::Retrying, JobState::Queued) => true,
            (JobState::Retrying, JobState::Failed) => true,
            (JobState::Retrying, JobState::Cancelled) => true,

            (JobState::TimedOut, JobState::Retrying) => true,
            (JobState::TimedOut, JobState::Failed) => true,
            (JobState::TimedOut, JobState::Cancelled) => true,

            _ => false,
        }
    }
}

impl fmt::Display for JobState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}", self)
    }
}

/// Cryptographically sealed execution output returned by worker node
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct JobResult {
    pub result_id: Uuid,
    pub job_id: Uuid,
    pub node_id: Uuid,
    pub exit_code: i32,
    pub stdout: String,
    pub stderr: String,
    /// SHA-256 of stdout concatenated with exit_code and return buffers
    pub result_digest: String,
    /// Exact WebAssembly fuel units consumed
    pub fuel_consumed: u64,
    /// Wall-clock execution duration in milliseconds
    pub wall_time_ms: u64,
    /// Peak linear memory allocated in bytes
    pub peak_memory_bytes: u64,
    /// Ed25519 signature of the `result_digest` using the worker node's private key
    pub node_signature: String,
    pub completed_at_ms: i64,
}

impl JobResult {
    /// Computes canonical result digest string for node signing and verification
    pub fn compute_digest(exit_code: i32, stdout: &str, stderr: &str, fuel: u64) -> String {
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        hasher.update(exit_code.to_le_bytes());
        hasher.update(stdout.as_bytes());
        hasher.update(stderr.as_bytes());
        hasher.update(fuel.to_le_bytes());
        hex::encode(hasher.finalize())
    }
}

/// Explicit renewable job lease contract between Control Plane and Worker Node
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct JobLease {
    pub lease_id: Uuid,
    pub job_id: Uuid,
    pub node_id: Uuid,
    pub issued_at_ms: i64,
    pub expires_at_ms: i64,
    pub renewed_at_ms: i64,
    pub term: u32,
}

impl JobLease {
    pub fn new(job_id: Uuid, node_id: Uuid, duration_ms: u64) -> Self {
        let now = chrono::Utc::now().timestamp_millis();
        Self {
            lease_id: Uuid::new_v4(),
            job_id,
            node_id,
            issued_at_ms: now,
            expires_at_ms: now + duration_ms as i64,
            renewed_at_ms: now,
            term: 1,
        }
    }

    pub fn is_expired(&self, current_time_ms: i64) -> bool {
        current_time_ms > self.expires_at_ms
    }

    pub fn renew(&mut self, extension_ms: u64) {
        let now = chrono::Utc::now().timestamp_millis();
        self.renew_at(now, extension_ms);
    }

    pub fn renew_at(&mut self, now_ms: i64, extension_ms: u64) {
        self.renewed_at_ms = now_ms;
        self.expires_at_ms = now_ms + extension_ms as i64;
        self.term += 1;
    }
}

/// Full tracking record of a distributed job in the control plane
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct JobRecord {
    pub job_id: Uuid,
    pub spec: WorkloadSpec,
    pub state: JobState,
    pub assigned_node_id: Option<Uuid>,
    pub current_lease: Option<JobLease>,
    pub retry_count: u32,
    pub created_at_ms: i64,
    pub scheduled_at_ms: Option<i64>,
    pub started_at_ms: Option<i64>,
    pub completed_at_ms: Option<i64>,
    pub result: Option<JobResult>,
    pub error_message: Option<String>,
    pub credit_cost: Option<u64>,
}

impl JobRecord {
    pub fn new(spec: WorkloadSpec) -> Self {
        let now = chrono::Utc::now().timestamp_millis();
        Self {
            job_id: spec.workload_id,
            spec,
            state: JobState::Queued,
            assigned_node_id: None,
            current_lease: None,
            retry_count: 0,
            created_at_ms: now,
            scheduled_at_ms: None,
            started_at_ms: None,
            completed_at_ms: None,
            result: None,
            error_message: None,
            credit_cost: None,
        }
    }

    /// Applies state transition with strict validation
    pub fn transition_to(&mut self, next: JobState) -> Result<(), ProtocolError> {
        if !self.state.can_transition_to(next) {
            return Err(ProtocolError::InvalidStateTransition {
                from: self.state.to_string(),
                to: next.to_string(),
            });
        }
        let now = chrono::Utc::now().timestamp_millis();
        match next {
            JobState::Scheduled => self.scheduled_at_ms = Some(now),
            JobState::Running => self.started_at_ms = Some(now),
            JobState::Completed | JobState::Failed | JobState::Cancelled => {
                self.completed_at_ms = Some(now);
                self.current_lease = None;
            }
            JobState::Retrying => {
                self.retry_count += 1;
                self.assigned_node_id = None;
                self.current_lease = None;
            }
            _ => {}
        }
        self.state = next;
        Ok(())
    }
}

