        let rec2 = MeteringRecord::create(
            job_id,
            node_id,
            "digest123",
            "prov_pub".into(),
            "sub_pub".into(),
            usage,
            true,
        );

        // Idempotency keys must be strictly identical for the same job, node and digest
        assert_eq!(rec1.idempotency_key, rec2.idempotency_key);
        assert_eq!(rec1.credits_earned_by_node, 77);
    }
