#[cfg(test)]
mod tests {
    use super::*;
    use crate::node::{NodeDeviceType, NodeHardwareCapabilities, NodeTelemetry, ProviderPolicy};

    #[test]
    fn test_rpc_messages_serde() {
        let node_id = Uuid::new_v4();
        let job_id = Uuid::new_v4();
        let lease_id = Uuid::new_v4();

        // 1. RegisterNodeRequest
        let reg_req = RegisterNodeRequest {
            public_key: "abc123pubkey".into(),
            device_type: NodeDeviceType::AndroidSmartphone,
            capabilities: NodeHardwareCapabilities::default(),
            initial_telemetry: NodeTelemetry::default(),
            initial_policy: ProviderPolicy::default(),
            region: "us-west".into(),
            is_simulated: true,
            enrollment_signature: "sig123".into(),
            timestamp_ms: 1000,
        };
        let reg_json = serde_json::to_string(&reg_req).unwrap();
        let reg_deser: RegisterNodeRequest = serde_json::from_str(&reg_json).unwrap();
        assert_eq!(reg_deser.region, "us-west");
        assert_eq!(reg_deser.public_key, "abc123pubkey");

        // 2. RegisterNodeResponse
        let reg_resp = RegisterNodeResponse {
            node_id,
            auth_token: "tok_xyz".into(),
            control_plane_pubkey: "cp_pub".into(),
            heartbeat_interval_secs: 15,
        };
        let resp_json = serde_json::to_string(&reg_resp).unwrap();
        let resp_deser: RegisterNodeResponse = serde_json::from_str(&resp_json).unwrap();
        assert_eq!(resp_deser.node_id, node_id);
        assert_eq!(resp_deser.heartbeat_interval_secs, 15);

        // 3. HeartbeatRequest & Response with NodeRemoteCommand
        let hb_req = HeartbeatRequest {
            node_id,
            telemetry: NodeTelemetry::default(),
            policy: ProviderPolicy::default(),
            timestamp_ms: 2000,
            signature: "sig_hb".into(),
        };
        let hb_json = serde_json::to_string(&hb_req).unwrap();
        assert!(hb_json.contains("sig_hb"));

        let hb_resp = HeartbeatResponse {
            acknowledged: true,
            pending_jobs_count: 2,
            command: Some(NodeRemoteCommand::CancelJob { job_id }),
        };
        let hb_resp_json = serde_json::to_string(&hb_resp).unwrap();
        let hb_resp_deser: HeartbeatResponse = serde_json::from_str(&hb_resp_json).unwrap();
        assert!(hb_resp_deser.acknowledged);
        assert_eq!(hb_resp_deser.pending_jobs_count, 2);

        // Test other NodeRemoteCommands
        let pause_cmd = NodeRemoteCommand::PauseExecution;
        let resume_cmd = NodeRemoteCommand::ResumeExecution;
        let renum_cmd = NodeRemoteCommand::ReEnumerateCapabilities;
        assert!(serde_json::to_string(&pause_cmd).unwrap().contains("pause_execution"));
        assert!(serde_json::to_string(&resume_cmd).unwrap().contains("resume_execution"));
        assert!(serde_json::to_string(&renum_cmd).unwrap().contains("re_enumerate_capabilities"));

        // 4. JobDispatchMessage & PollJob
        let dispatch = JobDispatchMessage {
            job_id,
            lease_id,
            lease_expires_at_ms: 50000,
            spec: WorkloadSpec::default(),
            wasm_bytes: Some(vec![0x00, 0x61, 0x73, 0x6d]),
            dispatched_at_ms: 25000,
        };
        let poll_resp = PollJobResponse { job: Some(dispatch) };
        let poll_json = serde_json::to_string(&poll_resp).unwrap();
        let poll_deser: PollJobResponse = serde_json::from_str(&poll_json).unwrap();
        assert!(poll_deser.job.is_some());
        assert_eq!(poll_deser.job.unwrap().job_id, job_id);

        // 5. RenewLease
        let renew_req = RenewLeaseRequest { job_id, node_id, lease_id };
        let renew_resp = RenewLeaseResponse {
            renewed: true,
            lease_id,
            expires_at_ms: 60000,
            reason: None,
        };
        let renew_json = serde_json::to_string(&renew_req).unwrap();
        let renew_resp_json = serde_json::to_string(&renew_resp).unwrap();
        assert!(renew_json.contains(&job_id.to_string()));
        assert!(renew_resp_json.contains("renewed"));

        // 6. SubmitJobResult
        let submit_res_req = SubmitJobResultRequest {
            node_id,
            lease_id: Some(lease_id),
            result: JobResult {
                result_id: Uuid::new_v4(),
                job_id,
                node_id,
                exit_code: 0,
                stdout: "ok".into(),
                stderr: "".into(),
                result_digest: "sha_xyz".into(),
                fuel_consumed: 100,
                wall_time_ms: 10,
                peak_memory_bytes: 1024,
                node_signature: "sig_node".into(),
                completed_at_ms: 2000,
            },
        };
        let submit_res_resp = SubmitJobResultResponse {
            accepted: true,
            verification_status: "VERIFIED".into(),
            credits_earned: 50,
        };
        assert!(serde_json::to_string(&submit_res_req).unwrap().contains("sha_xyz"));
        assert!(serde_json::to_string(&submit_res_resp).unwrap().contains("VERIFIED"));

        // 7. SystemHealthResponse, ListNodesResponse, ListJobsResponse
        let health = SystemHealthResponse {
            status: "HEALTHY".into(),
            active_nodes: 5,
            idle_nodes: 3,
            paused_nodes: 1,
            offline_nodes: 0,
            queue_depth: 2,
            running_jobs: 1,
            completed_jobs: 100,
            failed_jobs: 2,
            average_scheduling_latency_ms: 4.5,
            uptime_secs: 3600,
        };
        assert!(serde_json::to_string(&health).unwrap().contains("HEALTHY"));

        let list_nodes = ListNodesResponse { nodes: vec![], total: 0 };
        let list_jobs = ListJobsResponse { jobs: vec![], total: 0 };
        assert_eq!(serde_json::from_str::<ListNodesResponse>(&serde_json::to_string(&list_nodes).unwrap()).unwrap().total, 0);
        assert_eq!(serde_json::from_str::<ListJobsResponse>(&serde_json::to_string(&list_jobs).unwrap()).unwrap().total, 0);
    }
}

use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RuntimeType {
    /// WebAssembly with WASI Preview 1 sandboxing (Default production runtime)
    WasmWasi,
    /// Future extensible AI inference runtime (e.g. ONNX/TFLite)
    AiInference,
    /// Future native sandboxed container (Linux/MicroVM)
    NativeSandbox,
}

impl Default for RuntimeType {
    fn default() -> Self {
        Self::WasmWasi
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ResourceLimits {
    /// Maximum WebAssembly execution fuel (gas) to prevent infinite loops (e.g. 50_000_000)
    pub max_fuel: u64,
    /// Maximum memory allocation ceiling in bytes (e.g. 64 * 1024 * 1024 = 64MB)
    pub max_memory_bytes: u64,
    /// Maximum ephemeral disk storage in bytes
    pub max_storage_bytes: u64,
    /// Hard execution timeout in milliseconds (deterministic watchdog)
    pub timeout_ms: u64,
    /// Maximum stdout/stderr output size in bytes to prevent buffer exhaustion attacks
    pub max_output_bytes: usize,
}

impl Default for ResourceLimits {
    fn default() -> Self {
        Self {
            max_fuel: 50_000_000,
            max_memory_bytes: 64 * 1024 * 1024, // 64 MB
            max_storage_bytes: 10 * 1024 * 1024, // 10 MB
            timeout_ms: 30_000,                  // 30 seconds
            max_output_bytes: 1024 * 1024,       // 1 MB
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NetworkPolicy {
    /// Sandboxed execution with zero network access (Strongest isolation)
    None,
    /// Outbound HTTP/HTTPS requests to pre-approved endpoints only
    OutboundRestricted,
    /// Full network access (Requires elevated provider consent)
    Full,
}

impl Default for NetworkPolicy {
    fn default() -> Self {
        Self::None
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RequiredCapabilities {
    /// Target CPU architectures (e.g. ["aarch64", "x86_64"])
    pub architectures: Vec<String>,
    /// Minimum free RAM required in megabytes
    pub min_ram_mb: u64,
    /// Minimum battery percentage required (0..100)
    pub min_battery_pct: u8,
    /// Whether node must be plugged into AC / wireless charger
    pub require_charging: bool,
    /// Whether node must be connected to unmetered network (e.g. Wi-Fi / Ethernet)
    pub require_unmetered_network: bool,
    /// Maximum acceptable thermal level string (e.g. "NONE", "LIGHT", "MODERATE")
    pub max_thermal_level: String,
    /// Optional hardware acceleration (e.g. "npu", "gpu", "none")
    pub required_accelerator: Option<String>,
}

impl Default for RequiredCapabilities {
    fn default() -> Self {
        Self {
            architectures: vec!["aarch64".into(), "x86_64".into()],
            min_ram_mb: 256,
            min_battery_pct: 30,
            require_charging: false,
            require_unmetered_network: true,
            max_thermal_level: "MODERATE".into(),
            required_accelerator: None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RetryPolicy {
    /// Maximum times a failed job may be rescheduled onto a different node
    pub max_retries: u32,
    /// Base backoff delay between retries in milliseconds
    pub initial_backoff_ms: u64,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_retries: 3,
            initial_backoff_ms: 1000,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum VerificationPolicy {
    /// Zero verification overhead for best-effort / low-cost jobs
    None,
    /// Single node execution, trusts signature and hash
    SingleNode,
    /// Compares output digest against a known expected SHA-256 digest
    HashMatch {
        expected_digest: String,
    },
    /// Redundant execution with consensus quorum across multiple untrusted nodes.
    /// Invariant: M-of-N protects against non-colluding nodes; it DOES NOT protect against colluding groups.
    MOfN {
        replicas: u32,
        threshold: u32,
    },
    /// Spot check by re-executing on a deterministic verification node
    DeterministicReplay,
    /// Restricts execution only to nodes with high historical reputation
    TrustedNode {
        min_reputation: u32,
    },
    /// Delegated verification via custom external verifier
    CustomVerifier {
        verifier_endpoint: String,
    },
    /// Random spot check (probabilistic second execution)
    SpotCheck {
        probability_pct: u8,
    },
    /// Reserved for hardware TEE/AVF pKVM attestation (currently UNSUPPORTED on non-TEE devices)
    TeeAttested,
}

impl Default for VerificationPolicy {
    fn default() -> Self {
        Self::SingleNode
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[repr(u8)]
pub enum WorkloadPriority {
    Low = 0,
    Normal = 10,
    High = 20,
    Critical = 30,
}

impl Default for WorkloadPriority {
    fn default() -> Self {
        Self::Normal
    }
}

/// Versioned Workload Specification (Section 6)
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct WorkloadSpec {
    /// Unique workload identifier (UUID v4)
    pub workload_id: Uuid,
    /// Semver specification version (e.g. "1.0.0")
    pub spec_version: String,
    /// Human-readable workload name
    pub name: String,
    /// Target runtime environment
    pub runtime: RuntimeType,
    /// SHA-256 hash of the binary artifact (e.g. wasm module)
    pub artifact_sha256: String,
    /// Size of binary artifact in bytes
    pub artifact_size_bytes: u64,
    /// URL or storage key where artifact can be retrieved
    pub artifact_uri: String,
    /// Workload entrypoint function name (e.g. "_start" or "run")
    pub entrypoint: String,
    /// Command line arguments passed into sandboxed WASI module
    pub args: Vec<String>,
    /// Environment variables permitted inside sandbox
    pub env_vars: Vec<(String, String)>,
    /// Strict resource constraints
    pub limits: ResourceLimits,
    /// Network connectivity constraints
    pub network_policy: NetworkPolicy,
    /// Scheduling node requirements
    pub required_capabilities: RequiredCapabilities,
    /// Fault tolerance policy
    pub retry_policy: RetryPolicy,
    /// Result integrity policy
    pub verification_policy: VerificationPolicy,
    /// Queue scheduling priority
    pub priority: WorkloadPriority,
    /// Base64-encoded Ed25519 signature of submitter over the canonical spec bytes
    pub submitter_signature: String,
    /// Submitter public key hex or base64
    pub submitter_pubkey: String,
    /// Timestamp of submission (Unix epoch milliseconds)
    pub created_at_ms: i64,
}

impl WorkloadSpec {
    /// Generates canonical bytes representation for cryptographic signing and verification
    pub fn canonical_bytes_for_signing(&self) -> Vec<u8> {
        format!(
            "{}:{}:{}:{}:{}:{}",
            self.workload_id,
            self.spec_version,
            self.artifact_sha256,
            self.limits.max_fuel,
            self.limits.max_memory_bytes,
            self.created_at_ms
        )
        .into_bytes()
    }
}

impl Default for WorkloadSpec {
    fn default() -> Self {
        Self {
            workload_id: Uuid::new_v4(),
            spec_version: "1.0.0".into(),
            name: "default_workload".into(),
            runtime: RuntimeType::WasmWasi,
            artifact_sha256: "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855".into(),
            artifact_size_bytes: 0,
            artifact_uri: "inline://".into(),
            entrypoint: "_start".into(),
            args: vec![],
            env_vars: vec![],
            limits: ResourceLimits::default(),
            network_policy: NetworkPolicy::None,
            required_capabilities: RequiredCapabilities::default(),
            retry_policy: RetryPolicy::default(),
            verification_policy: VerificationPolicy::SingleNode,
            priority: WorkloadPriority::Normal,
            submitter_signature: "".into(),
            submitter_pubkey: "".into(),
            created_at_ms: 1000,
        }
    }
}

