use crate::filter::evaluate_node_eligibility;
use crate::policy::SchedulerConfig;
use crate::scorer::score_node;
use spaas_protocol::error::ProtocolError;
use spaas_protocol::node::NodeRecord;
use spaas_protocol::workload::{VerificationPolicy, WorkloadSpec};
use tracing::{debug, info};
use uuid::Uuid;

#[derive(Debug, Clone)]
pub struct ScoredCandidate {
    pub node_id: Uuid,
    pub score: f64,
    pub reliability_score: f32,
}

pub struct EdgeScheduler {
    config: SchedulerConfig,
}

impl EdgeScheduler {
    pub fn new(config: SchedulerConfig) -> Self {
        Self { config }
    }

    pub fn config(&self) -> &SchedulerConfig {
        &self.config
    }

    /// Evaluates all available registered nodes, filters out ineligible candidates,
    /// scores the remainder, and selects the optimal node(s) for dispatch.
    pub fn schedule_workload(
        &self,
        spec: &WorkloadSpec,
        nodes: &[NodeRecord],
    ) -> Result<Vec<Uuid>, ProtocolError> {
        let mut candidates: Vec<ScoredCandidate> = Vec::new();

        for node in nodes {
            if evaluate_node_eligibility(node, spec).is_ok() {
                let score = score_node(node, &self.config.weights);
                candidates.push(ScoredCandidate {
                    node_id: node.node_id,
                    score,
                    reliability_score: node.telemetry.reliability_score,
                });
            }
        }

        if candidates.is_empty() {
            debug!(workload_id = %spec.workload_id, "No eligible nodes matched workload requirements");
            return Err(ProtocolError::NoEligibleNodeFound);
        }

        // Sort descending by score
        candidates.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap_or(std::cmp::Ordering::Equal));

        // Determine how many nodes are needed based on verification policy
        let required_nodes_count = match &spec.verification_policy {
            VerificationPolicy::None => 1,
            VerificationPolicy::SingleNode => 1,
            VerificationPolicy::HashMatch { .. } => 1,
            VerificationPolicy::MOfN { replicas, .. } => *replicas as usize,
            VerificationPolicy::DeterministicReplay => 2,
            VerificationPolicy::TrustedNode { min_reputation } => {
                candidates.retain(|c| (c.reliability_score * 100.0) >= *min_reputation as f32);
                1
            }
            VerificationPolicy::CustomVerifier { .. } => 1,
            VerificationPolicy::SpotCheck { .. } => 1,
            VerificationPolicy::TeeAttested => 1,
        };

        if candidates.len() < required_nodes_count {
            return Err(ProtocolError::NoEligibleNodeFound);
        }

        let selected: Vec<Uuid> = candidates
            .into_iter()
            .take(required_nodes_count)
            .map(|c| c.node_id)
            .collect();

        info!(
            workload_id = %spec.workload_id,
            nodes_assigned = ?selected,
            "Workload scheduled successfully"
        );

        Ok(selected)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use spaas_protocol::node::*;
    use spaas_protocol::workload::*;

    #[test]
    fn test_edge_scheduler_selection() {
        let scheduler = EdgeScheduler::new(SchedulerConfig::default());
        let spec = WorkloadSpec {
            workload_id: Uuid::new_v4(),
            spec_version: "1.0.0".into(),
            name: "test".into(),
            runtime: RuntimeType::WasmWasi,
            artifact_sha256: "hash".into(),
            artifact_size_bytes: 100,
            artifact_uri: "uri".into(),
            entrypoint: "_start".into(),
            args: vec![],
            env_vars: vec![],
            limits: ResourceLimits::default(),
            network_policy: NetworkPolicy::None,
            required_capabilities: RequiredCapabilities::default(),
            retry_policy: RetryPolicy::default(),
            verification_policy: VerificationPolicy::SingleNode,
            priority: WorkloadPriority::Normal,
            submitter_signature: "sig".into(),
            submitter_pubkey: "pub".into(),
            created_at_ms: 1000,
        };

        let node1 = NodeRecord {
            node_id: Uuid::new_v4(),
            public_key: "k1".into(),
            device_type: NodeDeviceType::AndroidSmartphone,
            enrollment: EnrollmentStatus::Enrolled,
            state: NodeState::Idle,
            capabilities: NodeHardwareCapabilities::default(),
            telemetry: NodeTelemetry {
                battery_pct: 90,
                charging_state: ChargingState::ChargingAc,
                thermal_status: ThermalStatus::None,
                ..Default::default()
            },
            policy: ProviderPolicy::default(),
            qualification: None,
            enrolled_at_ms: 0,
            last_heartbeat_ms: 0,
            region: "us".into(),
            is_simulated: false,
        };

        let node2 = NodeRecord {
            node_id: Uuid::new_v4(),
            public_key: "k2".into(),
            device_type: NodeDeviceType::AndroidSmartphone,
            enrollment: EnrollmentStatus::Enrolled,
            state: NodeState::Idle,
            capabilities: NodeHardwareCapabilities::default(),
            telemetry: NodeTelemetry {
                battery_pct: 45,
                charging_state: ChargingState::ChargingUsb,
                thermal_status: ThermalStatus::Moderate,
                ..Default::default()
            },
            policy: ProviderPolicy::default(),
            qualification: None,
            enrolled_at_ms: 0,
            last_heartbeat_ms: 0,
            region: "us".into(),
            is_simulated: false,
        };

        let nodes = vec![node1.clone(), node2.clone()];
        let selected = scheduler.schedule_workload(&spec, &nodes).unwrap();
        assert_eq!(selected.len(), 1);
        assert_eq!(selected[0], node1.node_id);

        assert_eq!(scheduler.config().max_queue_capacity, 10_000);

        // Test 1: Empty nodes list
        assert!(matches!(scheduler.schedule_workload(&spec, &[]), Err(ProtocolError::NoEligibleNodeFound)));

        // Test 2: MOfN selection
        let mut m_of_n_spec = spec.clone();
        m_of_n_spec.verification_policy = VerificationPolicy::MOfN { replicas: 2, threshold: 2 };
        let m_selected = scheduler.schedule_workload(&m_of_n_spec, &nodes).unwrap();
        assert_eq!(m_selected.len(), 2);

        // Test 3: DeterministicReplay selection
        let mut replay_spec = spec.clone();
        replay_spec.verification_policy = VerificationPolicy::DeterministicReplay;
        let replay_selected = scheduler.schedule_workload(&replay_spec, &nodes).unwrap();
        assert_eq!(replay_selected.len(), 2);

        // Test 4: TrustedNode filtering
        let mut trusted_spec = spec.clone();
        trusted_spec.verification_policy = VerificationPolicy::TrustedNode { min_reputation: 90 };
        let mut low_nodes = nodes.clone();
        low_nodes[0].telemetry.reliability_score = 0.4;
        low_nodes[1].telemetry.reliability_score = 0.4;
        assert!(matches!(scheduler.schedule_workload(&trusted_spec, &low_nodes), Err(ProtocolError::NoEligibleNodeFound)));

        // If at least one node has high reputation, scheduling succeeds
        low_nodes[0].telemetry.reliability_score = 0.95;
        let trusted_selected = scheduler.schedule_workload(&trusted_spec, &low_nodes).unwrap();
        assert_eq!(trusted_selected, vec![low_nodes[0].node_id]);

        // Test other verification policies: None, HashMatch, CustomVerifier, SpotCheck, TeeAttested
        let mut policy_spec = spec.clone();
        policy_spec.verification_policy = VerificationPolicy::None;
        assert_eq!(scheduler.schedule_workload(&policy_spec, &nodes).unwrap().len(), 1);

        policy_spec.verification_policy = VerificationPolicy::HashMatch { expected_digest: "hash".into() };
        assert_eq!(scheduler.schedule_workload(&policy_spec, &nodes).unwrap().len(), 1);

        policy_spec.verification_policy = VerificationPolicy::CustomVerifier { verifier_endpoint: "http://endpoint".into() };
        assert_eq!(scheduler.schedule_workload(&policy_spec, &nodes).unwrap().len(), 1);

        policy_spec.verification_policy = VerificationPolicy::SpotCheck { probability_pct: 10 };
        assert_eq!(scheduler.schedule_workload(&policy_spec, &nodes).unwrap().len(), 1);

        policy_spec.verification_policy = VerificationPolicy::TeeAttested;
        assert_eq!(scheduler.schedule_workload(&policy_spec, &nodes).unwrap().len(), 1);
    }
}

use crate::policy::SchedulerWeights;
use spaas_protocol::node::{ChargingState, NetworkType, NodeRecord, ThermalStatus};

/// Calculates a normalized scalar score (0.0 to 100.0+) for an eligible candidate node
pub fn score_node(node: &NodeRecord, weights: &SchedulerWeights) -> f64 {
    // 1. Charging status (0.0 or 100.0)
    let charging_score = match node.telemetry.charging_state {
        ChargingState::ChargingAc | ChargingState::ChargingWireless | ChargingState::Full => 100.0,
        ChargingState::ChargingUsb => 75.0,
        _ => 20.0,
    };

    // 2. Battery state of charge (0.0 - 100.0)
    let battery_score = (node.telemetry.battery_pct as f64).clamp(0.0, 100.0);

    // 3. Thermal headroom
    let thermal_score = match node.telemetry.thermal_status {
        ThermalStatus::None => 100.0,
        ThermalStatus::Light => 80.0,
        ThermalStatus::Moderate => 40.0,
        ThermalStatus::Severe => 10.0,
        _ => 0.0,
    };

    // 4. Network quality
    let network_score = match node.telemetry.network_type {
        NetworkType::Ethernet => 100.0,
        NetworkType::WifiUnmetered => 90.0,
        NetworkType::CellularMetered => 30.0,
        NetworkType::Vpn => 50.0,
        _ => 10.0,
    };

    // 5. Historical reliability
    let reliability_score = (node.telemetry.reliability_score as f64 * 100.0).clamp(0.0, 100.0);

    // 6. Ping latency
    let ping = node.telemetry.round_trip_ping_ms.unwrap_or(80) as f64;
    let latency_score = (100.0 - ping).clamp(0.0, 100.0);

    // 7. Current CPU load penalty
    let load_penalty = (node.telemetry.cpu_usage_pct as f64).clamp(0.0, 100.0);

    let composite_score = (charging_score * weights.charging_weight)
        + (battery_score * weights.battery_weight)
        + (thermal_score * weights.thermal_weight)
        + (network_score * weights.network_weight)
        + (reliability_score * weights.reliability_weight)
        + (latency_score * weights.latency_weight)
        - (load_penalty * weights.load_penalty_weight);

    composite_score.max(0.0)
}

#[cfg(test)]
mod tests {
    use super::*;
    use spaas_protocol::node::*;
    use uuid::Uuid;

    #[test]
    fn test_node_scoring_preferences() {
        let weights = SchedulerWeights::default();

        let node_excellent = NodeRecord {
            node_id: Uuid::new_v4(),
            public_key: "k1".into(),
            device_type: NodeDeviceType::AndroidSmartphone,
            enrollment: EnrollmentStatus::Enrolled,
            state: NodeState::Idle,
            capabilities: NodeHardwareCapabilities::default(),
            telemetry: NodeTelemetry {
                battery_pct: 95,
                charging_state: ChargingState::ChargingAc,
                thermal_status: ThermalStatus::None,
                network_type: NetworkType::WifiUnmetered,
                reliability_score: 1.0,
                cpu_usage_pct: 2.0,
                round_trip_ping_ms: Some(15),
                ..Default::default()
            },
            policy: ProviderPolicy::default(),
            qualification: None,
            enrolled_at_ms: 0,
            last_heartbeat_ms: 0,
            region: "us".into(),
            is_simulated: false,
        };

        let mut node_mediocre = node_excellent.clone();
        node_mediocre.node_id = Uuid::new_v4();
        node_mediocre.telemetry.battery_pct = 45;
        node_mediocre.telemetry.charging_state = ChargingState::Discharging;
        node_mediocre.telemetry.thermal_status = ThermalStatus::Moderate;
        node_mediocre.telemetry.network_type = NetworkType::CellularMetered;
        node_mediocre.telemetry.reliability_score = 0.7;
        node_mediocre.telemetry.cpu_usage_pct = 65.0;

        let score_exc = score_node(&node_excellent, &weights);
        let score_med = score_node(&node_mediocre, &weights);

        assert!(score_exc > score_med, "Excellent node must outscore mediocre node");
        assert!(score_exc >= 80.0);

        // Test other charging, thermal, and network variants
        let mut variant_node = node_excellent.clone();
        variant_node.telemetry.charging_state = ChargingState::ChargingUsb;
        variant_node.telemetry.thermal_status = ThermalStatus::Light;
        variant_node.telemetry.network_type = NetworkType::Ethernet;
        let score_var1 = score_node(&variant_node, &weights);
        assert!(score_var1 > 0.0);

        variant_node.telemetry.charging_state = ChargingState::NotCharging;
        variant_node.telemetry.thermal_status = ThermalStatus::Severe;
        variant_node.telemetry.network_type = NetworkType::Vpn;
        let score_var2 = score_node(&variant_node, &weights);
        assert!(score_var2 < score_var1);

        variant_node.telemetry.thermal_status = ThermalStatus::Critical;
        variant_node.telemetry.network_type = NetworkType::Unknown;
        let score_var3 = score_node(&variant_node, &weights);
        assert!(score_var3 <= score_var2);
    }
}

use crate::error::SecurityError;
use sha2::{Digest, Sha256};

/// Computes SHA-256 hash of arbitrary bytes and returns lower-case hex string
pub fn sha256_hex(data: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data);
    hex::encode(hasher.finalize())
}

/// Verifies that data matches expected SHA-256 hex string (case-insensitive)
pub fn verify_sha256(data: &[u8], expected_hex: &str) -> Result<(), SecurityError> {
    let actual_hex = sha256_hex(data);
    if !actual_hex.eq_ignore_ascii_case(expected_hex.trim()) {
        return Err(SecurityError::IntegrityCheckFailed {
            expected: expected_hex.to_string(),
            actual: actual_hex,
        });
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sha256_computation_and_verification() {
        let bytes = b"hello spaas edge computing";
        let hash = sha256_hex(bytes);
        assert_eq!(hash.len(), 64);
        assert!(verify_sha256(bytes, &hash).is_ok());
        assert!(verify_sha256(b"corrupted bytes", &hash).is_err());
    }
}

use crate::error::SecurityError;
use ed25519_dalek::{SigningKey, VerifyingKey};
use rand::rngs::OsRng;

#[derive(Clone)]
pub struct KeyPair {
    signing_key: SigningKey,
    verifying_key: VerifyingKey,
}

impl KeyPair {
    /// Generates a cryptographically secure fresh Ed25519 keypair
    pub fn generate() -> Self {
        let signing_key = SigningKey::generate(&mut OsRng);
        let verifying_key = signing_key.verifying_key();
        Self {
            signing_key,
            verifying_key,
        }
    }

    /// Reconstructs keypair from 32-byte private key seed
    pub fn from_secret_bytes(bytes: &[u8; 32]) -> Self {
        let signing_key = SigningKey::from_bytes(bytes);
        let verifying_key = signing_key.verifying_key();
        Self {
            signing_key,
            verifying_key,
        }
    }

    /// Reconstructs keypair from hex string
    pub fn from_secret_hex(hex_str: &str) -> Result<Self, SecurityError> {
        let bytes = hex::decode(hex_str)
            .map_err(|e| SecurityError::InvalidKey(format!("Hex decode failed: {e}")))?;
        if bytes.len() != 32 {
            return Err(SecurityError::InvalidKey(format!(
                "Invalid secret key length: expected 32 bytes, got {}",
                bytes.len()
            )));
        }
        let mut arr = [0u8; 32];
        arr.copy_from_slice(&bytes);
        Ok(Self::from_secret_bytes(&arr))
    }

    pub fn signing_key(&self) -> &SigningKey {
        &self.signing_key
    }

    pub fn verifying_key(&self) -> &VerifyingKey {
        &self.verifying_key
    }

    /// Returns public key as 32 bytes
    pub fn public_key_bytes(&self) -> [u8; 32] {
        self.verifying_key.to_bytes()
    }

    /// Returns public key as hex string
    pub fn public_key_hex(&self) -> String {
        hex::encode(self.public_key_bytes())
    }

    /// Returns secret key as hex string
    pub fn secret_key_hex(&self) -> String {
        hex::encode(self.signing_key.to_bytes())
    }
}

pub struct PublicKey(pub VerifyingKey);

impl PublicKey {
    pub fn from_hex(hex_str: &str) -> Result<Self, SecurityError> {
        let bytes = hex::decode(hex_str)
            .map_err(|e| SecurityError::InvalidKey(format!("Hex decode failed: {e}")))?;
        if bytes.len() != 32 {
            return Err(SecurityError::InvalidKey(format!(
                "Invalid public key length: expected 32 bytes, got {}",
                bytes.len()
            )));
        }
        let mut arr = [0u8; 32];
        arr.copy_from_slice(&bytes);
        let verifying_key = VerifyingKey::from_bytes(&arr)
            .map_err(|e| SecurityError::InvalidKey(format!("Invalid Ed25519 point: {e}")))?;
        Ok(Self(verifying_key))
    }

    pub fn to_hex(&self) -> String {
        hex::encode(self.0.to_bytes())
    }
}

